import {useCallback, useRef} from 'react'
import type {QueryFn} from './types'
import {useRelayEnvironment} from 'react-relay'
import {fetchSearchRepositories} from '@github-ui/item-picker/RepositoryPicker'
import type {Subscription} from 'relay-runtime'
import {getRepositorySearchQuery} from '@github-ui/item-picker/utils/get-repository-search-query'
import {formatQueryWithOrg} from './utils'

interface Props {
  org: string
}

export function useOrgOnlyRepos({org}: Props): QueryFn {
  const relayEnv = useRelayEnvironment()
  const searchedReposSubscription = useRef<Subscription | undefined>(undefined)

  const queryFn = useCallback(
    async (query: string) => {
      const formattedQuery = formatQueryWithOrg({org, query})

      const {repositories} = await fetchSearchRepositories(relayEnv, {
        query: getRepositorySearchQuery(formattedQuery),
        onStart: subscription => {
          searchedReposSubscription.current?.unsubscribe()
          searchedReposSubscription.current = subscription
        },
      })

      return repositories
    },
    [org, relayEnv],
  )

  return queryFn
}
